// SparkReportDetailModal — v8.0 SPARK IA Insights Trends deep-dive modal.
//
// Each report renders a rich body (KPI tiles, tables, breakdowns) plus the
// shared dark ARGUS observations box. The dispatch on reportKey lives in
// this file rather than a separate render module — SPARK's per-report
// content is more compact than ARION's so a single file is manageable.
//
// Architecture:
//   - Header: title · period · score chip · close
//   - Per-report rich body (renderSparkBody dispatch)
//   - ARGUS observations box (from rule library output)
//   - Footer: generated by ARGUS

import { X } from "lucide-react";
import { MonthlyScoreBars } from "./MonthlyScoreBars";
import { ArgusObservationsBox } from "./ArgusObservationsBox";
import { evaluateRules, type InsightRule } from "./insightRules";
import { SPARK_CONTACT_HEALTH_RULES } from "./sparkContactHealthRules";

interface SparkReportAnalysis {
  score: number;
  scoreInputs: Array<{ key: string; value: number | string | null; weight: number; note?: string }>;
  observations: string[];
  actions: string[];
  contextNote?: string;
}

interface SparkMeta {
  key: string;
  label: string;
  question: string;
  icon: any;
  weight: number;
}

interface Props {
  reportKey: string;
  meta: SparkMeta;
  report: SparkReportAnalysis;
  history?: Array<{ period_end: string; score: number }>;
  /** SparkEngineInput shape — all data the engines + rule libraries need. */
  inputs: any;
  /** Optional period label override. */
  periodLabel?: string;
  /** Tenant / workspace label for the ARGUS box header. */
  tenantLabel?: string;
  onClose: () => void;
}

/** Per-report rule-library lookup. As each library is built, add it here. */
const SPARK_RULES_BY_REPORT: Record<string, InsightRule[] | undefined> = {
  contact_health: SPARK_CONTACT_HEALTH_RULES,
  // lead_pipeline:    SPARK_LEAD_PIPELINE_RULES   (next commit)
  // campaign_perf:    SPARK_CAMPAIGN_PERF_RULES   (next commit)
  // marketing_attrib: SPARK_MARKETING_ATTRIB_RULES
  // segmentation:     SPARK_SEGMENTATION_RULES
  // automation_eff:   SPARK_AUTOMATION_EFF_RULES
  // retention_risk:   SPARK_RETENTION_RISK_RULES
  // revenue_attrib:   SPARK_REVENUE_ATTRIB_RULES
};

function bandColor(score: number): string {
  if (score >= 70) return "#16A34A";
  if (score >= 50) return "#EAB308";
  if (score > 0)   return "#DC2626";
  return "#94A3B8";
}

export function SparkReportDetailModal({
  reportKey,
  meta,
  report,
  history = [],
  inputs,
  periodLabel,
  tenantLabel,
  onClose,
}: Props) {
  const Icon = meta.icon;
  const scoreColor = bandColor(report.score);

  // v8.0 — when a rule library exists for this report, use it instead of
  // the engine's static observations. Fall back to engine output for
  // reports not yet migrated.
  const rules = SPARK_RULES_BY_REPORT[reportKey];
  let observations = report.observations;
  let actions = report.actions;
  if (rules) {
    const fired = evaluateRules(rules, inputs, { maxObservations: 8, maxActions: 5 });
    observations = fired.observations;
    actions = fired.actions;
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
    >
      <div
        className="bg-white rounded-lg shadow-2xl max-w-4xl w-full max-h-[90vh] flex flex-col"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-start justify-between gap-3 border-b border-slate-200 px-6 py-4 flex-shrink-0">
          <div className="flex items-start gap-3 min-w-0 flex-1">
            <div
              className="flex-shrink-0 h-10 w-10 rounded-full flex items-center justify-center"
              style={{ background: `${scoreColor}1A`, color: scoreColor }}
            >
              <Icon className="h-5 w-5" />
            </div>
            <div className="min-w-0">
              <h2 className="text-lg font-bold text-slate-900 truncate">{meta.label}</h2>
              <p className="text-xs text-slate-500 mt-0.5">{periodLabel || meta.question}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 flex-shrink-0">
            <div className="text-right">
              <div className="text-2xl font-bold tabular-nums" style={{ color: scoreColor }}>{report.score}</div>
              <div className="text-[9px] uppercase text-slate-400">/ 100</div>
            </div>
            <button
              onClick={onClose}
              className="p-1.5 hover:bg-slate-100 rounded text-slate-500"
              aria-label="Close"
            >
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
          {/* Score history */}
          {history.length >= 2 && (
            <div>
              <div className="flex items-center justify-between mb-1">
                <div className="text-[10px] uppercase font-semibold tracking-wide text-slate-500">Score history</div>
                <div className="text-[9px] text-slate-400">{history.length} period{history.length === 1 ? "" : "s"}</div>
              </div>
              <MonthlyScoreBars data={history} width={680} height={92} />
            </div>
          )}

          {/* Per-report rich body */}
          {renderSparkBody(reportKey, inputs, report)}

          {/* ARGUS observations box */}
          <ArgusObservationsBox
            observations={observations}
            actions={actions}
            reportLabel={meta.label}
            tenantLabel={tenantLabel}
            periodLabel={periodLabel}
          />
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-slate-200 px-6 py-3 bg-slate-50 rounded-b-lg flex-shrink-0">
          <div className="text-[11px] text-slate-500">
            Generated by{" "}
            <span className="font-semibold" style={{ color: "#A3E635" }}>ARGUS</span>
            {periodLabel && <> · {periodLabel.split("·")[0].trim()}</>}
          </div>
          <button
            onClick={onClose}
            className="px-4 py-1.5 text-xs bg-slate-900 text-white rounded hover:bg-slate-800"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Per-report rich body sections ────────────────────────────────────
function renderSparkBody(reportKey: string, inputs: any, report: SparkReportAnalysis) {
  switch (reportKey) {
    case "contact_health":
      return <ContactHealthBody inputs={inputs} />;
    default:
      // Fallback: surface engine's scoreInputs as basic KPI tiles.
      return <GenericBody report={report} />;
  }
}

// ── Contact Health rich body ─────────────────────────────────────────
function ContactHealthBody({ inputs }: { inputs: any }) {
  const t = inputs?.contact_totals || {};
  const recent = Number(inputs?.contact_recent?.new_contacts || 0);
  const active = Number(t.active || 0);
  const total = Number(t.total || 0);
  const email = Number(t.with_email || 0);
  const phone = Number(t.with_phone || 0);
  const opts = Number(t.sms_opt_outs || 0);
  const growthPct = active > 0 ? ((recent / active) * 100) : 0;
  const emailPct = active > 0 ? ((email / active) * 100) : 0;
  const phonePct = active > 0 ? ((phone / active) * 100) : 0;
  const days = Number(inputs?.period_days || 30);

  const sources = inputs?.top_sources || [];
  const tags = inputs?.top_tags || [];

  return (
    <>
      {/* Hero insight callout */}
      {active === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            No active contacts in SPARK yet. Either import your existing contact list or wire a form to capture inbound leads — every other Contact Health observation depends on this baseline.
          </p>
        </div>
      ) : recent === 0 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            <strong>0 new contacts</strong> in the last {days} days. Your acquisition funnel is dry — every day without inbound captures compounds into a lower revenue floor 60-90 days out. Inspect the top entry-page forms first.
          </p>
        </div>
      ) : growthPct < 2 ? (
        <div className="rounded-md border-l-4 border-amber-400 bg-amber-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-amber-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Contact base grew <strong>{growthPct.toFixed(1)}%</strong> over {days} days ({recent} new on a base of {active} active). Below the 5% benchmark for service businesses — at this pace, doubling the contact base takes ~{Math.round(70 / Math.max(growthPct, 0.5))} months.
          </p>
        </div>
      ) : (
        <div className="rounded-md border-l-4 border-emerald-400 bg-emerald-50 px-4 py-3">
          <div className="text-xs font-semibold uppercase text-emerald-800 tracking-wide mb-1">The insight</div>
          <p className="text-sm text-slate-800 leading-relaxed">
            Contact base grew <strong>{growthPct.toFixed(1)}%</strong> over {days} days. {recent} new contacts joined an active base of {fmtN(active)} — sustainable growth within the healthy range.
          </p>
        </div>
      )}

      {/* KPI tiles */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Kpi label="Active Contacts" value={fmtN(active)} sub={`${fmtN(total)} total in system`} accent="#EF6C33" />
        <Kpi label={`New (${days}d)`} value={fmtN(recent)} sub={`${growthPct.toFixed(1)}% growth rate`} accent={growthPct >= 5 ? "#16A34A" : growthPct >= 2 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Email Coverage" value={`${Math.round(emailPct)}%`} sub={`${fmtN(email)} of ${fmtN(active)}`} accent={emailPct >= 70 ? "#16A34A" : emailPct >= 50 ? "#EAB308" : "#DC2626"} />
        <Kpi label="Phone Coverage" value={`${Math.round(phonePct)}%`} sub={`${fmtN(phone)} of ${fmtN(active)} · ${fmtN(opts)} opt-outs`} accent={phonePct >= 50 ? "#16A34A" : phonePct >= 30 ? "#EAB308" : "#DC2626"} />
      </div>

      {/* Source distribution table */}
      {sources.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Acquisition sources</h3>
          <div className="rounded-md border border-slate-200 overflow-hidden">
            <table className="w-full text-xs">
              <thead className="bg-slate-50">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold text-slate-600">Source</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Contacts</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Active</th>
                  <th className="text-right px-3 py-2 font-semibold text-slate-600">Active rate</th>
                </tr>
              </thead>
              <tbody>
                {sources.slice(0, 10).map((s: any, i: number) => {
                  const n = Number(s.n || 0);
                  const act = Number(s.active_count || 0);
                  const rate = n > 0 ? (act / n) * 100 : 0;
                  return (
                    <tr key={i} className="border-t border-slate-100">
                      <td className="px-3 py-2 text-slate-900">{s.source || "(unknown)"}</td>
                      <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(n)}</td>
                      <td className="px-3 py-2 text-right text-slate-700 tabular-nums">{fmtN(act)}</td>
                      <td className="px-3 py-2 text-right tabular-nums" style={{ color: rate >= 70 ? "#16A34A" : rate >= 40 ? "#EAB308" : "#DC2626" }}>
                        {rate.toFixed(0)}%
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Top tags */}
      {tags.length > 0 && (
        <div>
          <h3 className="text-sm font-bold text-slate-900 mb-2">Top tags</h3>
          <div className="flex flex-wrap gap-2">
            {tags.slice(0, 12).map((tag: any, i: number) => (
              <span key={i} className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-slate-100 text-slate-700 text-xs">
                <span className="font-medium">{tag.name}</span>
                <span className="text-[10px] text-slate-500">{fmtN(Number(tag.n))}</span>
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Channel reachability summary */}
      <div>
        <h3 className="text-sm font-bold text-slate-900 mb-2">Channel reachability</h3>
        <div className="grid grid-cols-2 gap-3">
          <ReachBar label="Email" pct={emailPct} count={email} total={active} color="#1A7DB5" />
          <ReachBar label="SMS" pct={phonePct} count={phone} total={active} color="#EF6C33" />
        </div>
      </div>
    </>
  );
}

// ── Generic fallback body ────────────────────────────────────────────
function GenericBody({ report }: { report: SparkReportAnalysis }) {
  const numericInputs = report.scoreInputs.filter((s) => s.value !== null && s.value !== undefined);
  if (numericInputs.length === 0) return null;
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
      {numericInputs.slice(0, 4).map((k) => (
        <Kpi
          key={k.key}
          label={k.key}
          value={String(k.value)}
          sub={`${Math.round(k.weight * 100)}% of score`}
          accent="#EF6C33"
        />
      ))}
    </div>
  );
}

// ── UI atoms ─────────────────────────────────────────────────────────
function Kpi({ label, value, sub, accent }: { label: string; value: string; sub: string; accent: string }) {
  return (
    <div className="rounded-md border border-slate-200 bg-white px-3 py-2" style={{ borderTopWidth: 3, borderTopColor: accent }}>
      <div className="text-[10px] uppercase font-semibold text-slate-500 tracking-wide">{label}</div>
      <div className="text-lg font-bold text-slate-900 tabular-nums mt-0.5">{value}</div>
      <div className="text-[10px] text-slate-400 mt-0.5">{sub}</div>
    </div>
  );
}

function ReachBar({ label, pct, count, total, color }: { label: string; pct: number; count: number; total: number; color: string }) {
  return (
    <div className="rounded-md border border-slate-200 bg-white p-3">
      <div className="flex items-center justify-between mb-1">
        <span className="text-xs font-semibold text-slate-700">{label}</span>
        <span className="text-xs tabular-nums text-slate-600">{Math.round(pct)}%</span>
      </div>
      <div className="h-2 rounded-full bg-slate-100 overflow-hidden">
        <div className="h-full rounded-full transition-all" style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: color }} />
      </div>
      <div className="text-[10px] text-slate-400 mt-1.5">{fmtN(count)} of {fmtN(total)} active contacts</div>
    </div>
  );
}

function fmtN(n: number): string {
  if (!isFinite(n)) return "0";
  return n.toLocaleString();
}

export default SparkReportDetailModal;
